def add_components(apps, schema_editor):
    HrSettings = apps.get_model("hr", "HrSettings")
    SalaryComponent = apps.get_model("hr", "SalaryComponent")
    Account = apps.get_model("ledger", "Account")
    for s in HrSettings.objects.all():
        account = Account.objects.filter(entity_id=s.entity_id, code="5100").first()
        if account is None:
            continue
        for code, en, ar, gosi, eosb, ot, unpaid in COMPONENTS:
            SalaryComponent.objects.get_or_create(entity_id=s.entity_id, code=code, defaults=dict(
                name_en=en, name_ar=ar, counts_for_gosi=gosi, counts_for_eosb=eosb, counts_for_overtime_base=ot,
                deducted_for_unpaid_leave=unpaid, expense_account=account, source="system"))


